// Build digest email HTML
const items = $input.first().json;
const byCode = {};
items.forEach(i => {
  const key = `${i.source}:${i.guideline_code}`;
  if (!byCode[key]) byCode[key] = { source: i.source, code: i.guideline_code, title: i.title, count: 0, oldest: i.created_at };
  byCode[key].count++;
  if (i.created_at < byCode[key].oldest) byCode[key].oldest = i.created_at;
});
const groups = Object.values(byCode).sort((a, b) => a.oldest.localeCompare(b.oldest));

const rows = groups.map(g => `<tr><td><strong>${g.source}</strong></td><td><code>${g.code}</code></td><td>${g.title}</td><td>${g.count} chunks</td><td>${new Date(g.oldest).toLocaleDateString()}</td></tr>`).join('\n');

const html = `<h2>📋 ${groups.length} guidelines en attente de validation</h2>
<p>${items.length} chunks au total. Veuillez les valider sur <a href="${$env.VERCEL_BASE_URL}/admin/guidelines">l'interface admin</a>.</p>
<table border="1" cellpadding="6" style="border-collapse:collapse">
<thead><tr><th>Source</th><th>Code</th><th>Titre</th><th>Chunks</th><th>Plus ancien</th></tr></thead>
<tbody>${rows}</tbody></table>
<p style="font-size:12px;color:#888">Email automatique envoyé chaque heure si > 5 guidelines en attente.</p>`;

return [{ json: { html, count: groups.length, total_chunks: items.length } }];
